export function validateDIGESTIVELIVERSeed(): void {
  const slugs = new Set(
    DIGESTIVE_LIVER_STRUCTURES.map((structure) => structure.slug),
  );
  if (slugs.size !== DIGESTIVE_LIVER_STRUCTURES.length) {
    throw new Error(
      'Digestive system - liver seed contains duplicate structure slugs.',
    );
  }
  const meshNames = new Set(
    DIGESTIVE_LIVER_STRUCTURES.map((structure) => structure.meshName),
  );
  if (meshNames.size !== DIGESTIVE_LIVER_STRUCTURES.length) {
    throw new Error(
      'Digestive system - liver seed contains duplicate mesh names.',
    );
  }
  if (DIGESTIVE_LIVER_STRUCTURES.length !== 8) {
    throw new Error(
      'Digestive system - liver seed must contain exactly 8 structures.',
    );
  }
  for (const structure of DIGESTIVE_LIVER_STRUCTURES) {
    for (const relatedSlug of structure.relatedSlugs) {
      if (!slugs.has(relatedSlug)) {
        throw new Error(
          `Structure "${structure.slug}" references unknown related slug "${relatedSlug}".`,
        );
      }
    }
    if (structure.references.length === 0) {
      throw new Error(`Structure "${structure.slug}" has no references.`);
    }
    if (
      structure.meshName !== null &&
      !/^[a-z0-9_]+$/.test(structure.meshName)
    ) {
      throw new Error(
        `Structure "${structure.slug}" has an invalid mesh name "${structure.meshName}".`,
      );
    }
  }
}
